  const enc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const rnd=n=>Math.floor(Math.random()*n);
  const shuffle=a=>{const x=[...a];for(let i=x.length-1;i>0;i--){const j=rnd(i+1);[x[i],x[j]]=[x[j],x[i]]}return x};
  const scoreFmt=n=>(n||0).toLocaleString('de-DE');
  const defaultState=()=>({screen:'intro',players:[],birthdayId:null,mode:'classic',rounds:5,classicLevels:8,classicPlayerIndex:0,classicStep:0,classicLastId:null,classicEndReason:'',classicTie:false,usedClassicQuestions:[],order:[],firstIndex:null,turn:0,questionIndex:null,selected:null,responderId:null,redirectFrom:null,redirectTarget:null,jokerEffect:null,hiddenOptions:[],usedJokerThisQuestion:false,helper:'',result:null,pendingBonus:null,bonusTarget:null,isBonus:false,nextMultiplier:1,nextPenalty:false,currentEvent:null,currentFamily:null,usedQuestions:[],usedFinals:[],finalists:[],finalQuestion:null,finalEntries:{},finalResults:null,winnerId:null,giftRevealed:false,elapsedQuestion:0});
  let s;
  try{const migrated=!localStorage.getItem(STORE);const saved=JSON.parse(localStorage.getItem(STORE)||localStorage.getItem('bierlionaer-v1')||'null');s=saved&&Array.isArray(saved.players)&&MODES[saved.mode]&&['intro','setup','wheel','game','handover','event','family','finale','victory'].includes(saved.screen)?{...defaultState(),...saved}:defaultState();if(migrated&&saved){s.screen='setup';s.usedClassicQuestions=[];s.classicPlayerIndex=0;s.classicStep=0;}}catch{s=defaultState()}
  if(!['intro','setup','wheel','game','handover','event','family','finale','victory'].includes(s.screen))s.screen='intro';
