  const save=()=>{try{localStorage.setItem(STORE,JSON.stringify(s))}catch{}};
  const audio=()=>{if(!soundOn)return null;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();return audioContext}catch{return null}};
  function tone(freq=450,time=.12,type='sine',vol=.06,delay=0){const ctx=audio();if(!ctx)return;const t=ctx.currentTime+delay,o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+time);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+time+.02)}
  const sound={click:()=>tone(570,.07,'triangle',.035),good:()=>{tone(520,.15,'triangle',.07);tone(660,.16,'triangle',.07,.16);tone(840,.26,'triangle',.09,.34)},bad:()=>{tone(230,.22,'sawtooth',.055);tone(160,.32,'sawtooth',.045,.24)},event:()=>{tone(390,.14,'sawtooth',.06);tone(600,.19,'sawtooth',.06,.16)},win:()=>{[392,494,587,784,988].forEach((n,i)=>tone(n,.34,'triangle',.07,i*.16))}};
  function notice(text){clearTimeout(toastHandle);$('toast-root').textContent=text;toastHandle=setTimeout(()=>$('toast-root').textContent='',3400)}
  function stopTimer(){if(timerHandle)clearInterval(timerHandle);timerHandle=null;timerSeconds=null}
  function timerStart(seconds){stopTimer();timerSeconds=seconds;const el=$('timer-label');if(el)el.textContent=`⏱ ${seconds}s`;timerHandle=setInterval(()=>{timerSeconds--;const t=$('timer-label');if(t)t.textContent=`⏱ ${Math.max(0,timerSeconds)}s`;if(timerSeconds<=5&&timerSeconds>0)tone(520,.06,'square',.025);if(timerSeconds<=0){stopTimer();tone(175,.4,'sawtooth',.06);notice('ZEIT ABGELAUFEN! Die Quizleitung entscheidet über die Peinlichkeit.')}},1000)}
  function sorted(){return [...s.players].sort((a,b)=>b.score-a.score||s.players.indexOf(a)-s.players.indexOf(b))}
  function person(id){return s.players.find(p=>p.id===id)}
  function currentBaseId(){return s.mode==='classic'?s.order[s.classicPlayerIndex]||s.players[0]?.id:s.order[s.turn%s.order.length]||s.players[0]?.id}
  function opponentId(){return s.order[(s.turn+1)%s.order.length]}
  function activeId(){return s.isBonus?s.bonusTarget:(s.mode==='battle'?s.responderId:(s.redirectTarget||currentBaseId()))}
  function progress(){return s.mode==='classic'?Math.min(100,100*(s.classicPlayerIndex+(s.classicStep/Math.max(1,s.classicLevels)))/Math.max(1,s.players.length)):Math.min(100,100*s.turn/Math.max(1,s.rounds*s.players.length))}
  function rankHtml(active){return sorted().map((p,i)=>`<div class="score-row ${p.id===active?'active':''}"><span class="pos">${i+1}.</span><span class="avatar">${p.avatar}</span><span class="name" title="${enc(p.name)}">${enc(p.name)} ${p.id===s.birthdayId?'🎂':''}</span><span class="score">${scoreFmt(p.score)}</span></div>`).join('')}
